import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:flutter_localizations/flutter_localizations.dart';
import 'package:shared_preferences/shared_preferences.dart';

void main() { WidgetsFlutterBinding.ensureInitialized(); runApp(const Hayati()); }

const prayers = ['Fajr', 'Dhuhr', 'Asr', 'Maghrib', 'Isha'];
const names = {
  'ar': {'title':'حياتي','home':'الرئيسية','tasks':'المهام','prayer':'الصلاة','quran':'القرآن','settings':'الإعدادات','add':'إضافة مهمة','hint':'اكتب المهمة','done':'إنجاز اليوم','daily':'ورد اليوم','mark':'تم الإنجاز','empty':'لا توجد مهام','save':'حفظ','theme':'الوضع الداكن','language':'اللغة','progress':'تقدمك اليوم','delete':'حذف','fajr':'الفجر','dhuhr':'الظهر','asr':'العصر','maghrib':'المغرب','isha':'العشاء','qgoal':'هدف الورد (سورة أو جزء)','adhkar':'أذكار الصباح والمساء'},
  'tr': {'title':'Hayatım','home':'Ana Sayfa','tasks':'Görevler','prayer':'Namaz','quran':'Kur’an','settings':'Ayarlar','add':'Görev ekle','hint':'Görev yazın','done':'Bugünkü ilerleme','daily':'Günlük okuma','mark':'Tamamlandı','empty':'Görev yok','save':'Kaydet','theme':'Koyu tema','language':'Dil','progress':'Bugünkü ilerleme','delete':'Sil','fajr':'Sabah','dhuhr':'Öğle','asr':'İkindi','maghrib':'Akşam','isha':'Yatsı','qgoal':'Okuma hedefi (sure veya cüz)','adhkar':'Sabah ve akşam zikirleri'},
  'en': {'title':'Hayati','home':'Home','tasks':'Tasks','prayer':'Prayer','quran':'Quran','settings':'Settings','add':'Add task','hint':'Enter task','done':'Today’s progress','daily':'Daily reading','mark':'Completed','empty':'No tasks','save':'Save','theme':'Dark mode','language':'Language','progress':'Today’s progress','delete':'Delete','fajr':'Fajr','dhuhr':'Dhuhr','asr':'Asr','maghrib':'Maghrib','isha':'Isha','qgoal':'Reading goal (surah or juz)','adhkar':'Morning and evening adhkar'}
};

class Hayati extends StatefulWidget { const Hayati({super.key}); @override State<Hayati> createState()=>_HayatiState(); }
class _HayatiState extends State<Hayati> {
  SharedPreferences? prefs;
  String lang='ar', goal=''; bool dark=false; int tab=0;
  List<Map<String,dynamic>> tasks=[];
  Map<String,bool> prayerDone={}; Map<String,bool> quranDone={};
  String get today { final n=DateTime.now(); return '${n.year}-${n.month.toString().padLeft(2,'0')}-${n.day.toString().padLeft(2,'0')}'; }
  String t(String key)=>names[lang]?[key]??key;
  @override void initState(){super.initState(); load();}
  Future<void> load() async { final p=await SharedPreferences.getInstance(); if(!mounted)return; setState(() { prefs=p; lang=p.getString('lang')??'ar'; dark=p.getBool('dark')??false; goal=p.getString('goal')??''; try { tasks=(jsonDecode(p.getString('tasks')??'[]') as List).map((e)=>Map<String,dynamic>.from(e as Map)).toList(); } catch (_) { tasks=[]; } try {prayerDone=Map<String,bool>.from(jsonDecode(p.getString('prayers')??'{}') as Map);}catch(_){prayerDone={};} try {quranDone=Map<String,bool>.from(jsonDecode(p.getString('quran')??'{}') as Map);}catch(_){quranDone={};} }); }
  Future<void> persist() async { final p=prefs; if(p==null)return; await Future.wait([p.setString('lang',lang),p.setBool('dark',dark),p.setString('goal',goal),p.setString('tasks',jsonEncode(tasks)),p.setString('prayers',jsonEncode(prayerDone)),p.setString('quran',jsonEncode(quranDone))]); }
  void change(VoidCallback fn){setState(fn);persist();}
  Future<void> addTask() async {final c=TextEditingController(); final result=await showDialog<String>(context:context,builder:(ctx)=>AlertDialog(title:Text(t('add')),content:TextField(controller:c,autofocus:true,decoration:InputDecoration(hintText:t('hint'))),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(ctx,c.text.trim()),child:Text(t('save')))])); c.dispose(); if(result!=null&&result.isNotEmpty){change(()=>tasks.add({'id':DateTime.now().microsecondsSinceEpoch.toString(),'text':result,'done':false,'date':today}));}}
  int get completedPrayers=>prayers.where((p)=>prayerDone['$today:$p']==true).length;
  int get completedTasks=>tasks.where((x)=>x['date']==today&&x['done']==true).length;
  List<Map<String,dynamic>> get todayTasks=>tasks.where((x)=>x['date']==today).toList();
  Widget tile(String title, bool value, ValueChanged<bool?> onChange)=>Card(child:CheckboxListTile(title:Text(title),value:value,onChanged:onChange));
  Widget home(){final total=5+todayTasks.length+1;final done=completedPrayers+completedTasks+(quranDone[today]==true?1:0);return ListView(padding:const EdgeInsets.all(16),children:[Text(t('progress'),style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:12),Card(child:Padding(padding:const EdgeInsets.all(20),child:Column(children:[Text('$done / $total',style:Theme.of(context).textTheme.headlineMedium),const SizedBox(height:10),LinearProgressIndicator(value:done/total,minHeight:10)]))),const SizedBox(height:16),Text(t('prayer'),style:Theme.of(context).textTheme.titleLarge),...prayers.map((p)=>tile(t(p.toLowerCase()),prayerDone['$today:$p']==true,(v)=>change(()=>prayerDone['$today:$p']=v??false))),const SizedBox(height:10),Text(t('daily'),style:Theme.of(context).textTheme.titleLarge),tile(goal.isEmpty?t('qgoal'):goal,quranDone[today]==true,(v)=>change(()=>quranDone[today]=v??false)),const SizedBox(height:10),Text(t('tasks'),style:Theme.of(context).textTheme.titleLarge),...todayTasks.take(5).map(taskTile)]);}
  Widget taskTile(Map<String,dynamic> item)=>Card(child:Row(children:[Expanded(child:CheckboxListTile(title:Text(item['text'] as String),value:item['done']==true,onChanged:(v)=>change(()=>item['done']=v??false))),IconButton(tooltip:t('delete'),icon:const Icon(Icons.delete_outline),onPressed:()=>change(()=>tasks.removeWhere((x)=>x['id']==item['id'])))]));
  Widget taskPage()=>ListView(padding:const EdgeInsets.all(16),children:[...todayTasks.map(taskTile),if(todayTasks.isEmpty)Center(child:Padding(padding:const EdgeInsets.all(32),child:Text(t('empty'))))]);
  Widget prayerPage()=>ListView(padding:const EdgeInsets.all(16),children:[Text('$today · $completedPrayers / 5',style:Theme.of(context).textTheme.titleLarge),...prayers.map((p)=>tile(t(p.toLowerCase()),prayerDone['$today:$p']==true,(v)=>change(()=>prayerDone['$today:$p']=v??false)))]);
  Widget quranPage()=>ListView(padding:const EdgeInsets.all(16),children:[TextField(controller:TextEditingController(text:goal)..selection=TextSelection.collapsed(offset:goal.length),decoration:InputDecoration(labelText:t('qgoal'),border:const OutlineInputBorder()),onChanged:(v){goal=v;persist();}),const SizedBox(height:16),tile(t('mark'),quranDone[today]==true,(v)=>change(()=>quranDone[today]=v??false))]);
  Widget settings()=>ListView(padding:const EdgeInsets.all(16),children:[DropdownButtonFormField<String>(value:lang,decoration:InputDecoration(labelText:t('language')),items:const [DropdownMenuItem(value:'ar',child:Text('العربية')),DropdownMenuItem(value:'tr',child:Text('Türkçe')),DropdownMenuItem(value:'en',child:Text('English'))],onChanged:(v){if(v!=null)change(()=>lang=v);}),SwitchListTile(title:Text(t('theme')),value:dark,onChanged:(v)=>change(()=>dark=v))]);
  @override Widget build(BuildContext context){final labels=['home','tasks','prayer','quran','settings'];final icons=[Icons.home_outlined,Icons.checklist,Icons.check_circle_outline,Icons.menu_book_outlined,Icons.settings_outlined];return MaterialApp(debugShowCheckedModeBanner:false,locale:Locale(lang),supportedLocales:const [Locale('ar'),Locale('tr'),Locale('en')],localizationsDelegates:const [GlobalMaterialLocalizations.delegate,GlobalWidgetsLocalizations.delegate,GlobalCupertinoLocalizations.delegate],theme:ThemeData(colorSchemeSeed:Colors.teal,useMaterial3:true),darkTheme:ThemeData(colorSchemeSeed:Colors.teal,brightness:Brightness.dark,useMaterial3:true),themeMode:dark?ThemeMode.dark:ThemeMode.light,home:Scaffold(appBar:AppBar(title:Text(t('title'))),body:[home(),taskPage(),prayerPage(),quranPage(),settings()][tab],floatingActionButton:tab==1||tab==0?FloatingActionButton(onPressed:addTask,child:const Icon(Icons.add)):null,bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),destinations:List.generate(labels.length,(i)=>NavigationDestination(icon:Icon(icons[i]),label:t(labels[i]))))));}
}
